const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '单位换算表' },
      { kind: 'text', payload: '72 km/h 换算为 m/s（除以 3.6）' },
      { kind: 'text', payload: '项目' },
      { kind: 'text', payload: '内容' },
      { kind: 'text', payload: '已知量' },
      { kind: 'text', payload: 'v = 72 km/h' },
      { kind: 'text', payload: '换算关系' },
      { kind: 'text', payload: '1 m/s = 3.6 km/h' },
      { kind: 'text', payload: '换算算式' },
      { kind: 'text', payload: '72 ÷ 3.6 = 20.0' },
      { kind: 'text', payload: '结果' },
      { kind: 'text', payload: '20.0 m/s' },
      { kind: 'text', payload: '结果保留三位有效数字' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var left = W * 0.06;
    var right = W * 0.94;
    var tableTop = H * 0.20;
    var tableBottom = H * 0.90;
    var rows = 5;
    var rowH = (tableBottom - tableTop) / rows;
    var colX = left + (right - left) * 0.32;
    var pad = W * 0.018;

    var grid = [];
    for (var i = 0; i <= rows; i++) {
      var y = tableTop + rowH * i;
      grid.push(['M', left, y], ['L', right, y]);
    }
    grid.push(['M', left, tableTop], ['L', left, tableBottom]);
    grid.push(['M', right, tableTop], ['L', right, tableBottom]);
    grid.push(['M', colX, tableTop], ['L', colX, tableBottom]);

    var headerBg = [
      ['M', left, tableTop],
      ['L', right, tableTop],
      ['L', right, tableTop + rowH],
      ['L', left, tableTop + rowH],
      ['Z']
    ];

    var paths = [
      { id: 'headerBg', commands: headerBg },
      { id: 'grid', commands: grid }
    ];

    var children = [
      { type: 'path', pathId: 'headerBg', fill: '#EAF0F7' },
      { type: 'path', pathId: 'grid', fill: '#9AA9BB', stroke: { width: 1.5 } }
    ];

    function cell(idx, x, cy, color) {
      return {
        type: 'label',
        contentId: metrics[idx].contentId,
        anchor: { x: x, y: cy },
        hAlign: 'left',
        vAlign: 'middle',
        color: color || '#1F2A37'
      };
    }

    children.push({
      type: 'label', contentId: metrics[0].contentId,
      anchor: { x: W / 2, y: H * 0.07 },
      hAlign: 'center', vAlign: 'middle', color: '#12263A'
    });
    children.push({
      type: 'label', contentId: metrics[1].contentId,
      anchor: { x: W / 2, y: H * 0.135 },
      hAlign: 'center', vAlign: 'middle', color: '#44576B'
    });

    var headerY = tableTop + rowH * 0.5;
    children.push(cell(2, left + pad, headerY, '#12263A'));
    children.push(cell(3, colX + pad, headerY, '#12263A'));

    var dataRows = [[4, 5], [6, 7], [8, 9], [10, 11]];
    for (var r = 0; r < dataRows.length; r++) {
      var cy = tableTop + rowH * (r + 1) + rowH * 0.5;
      children.push(cell(dataRows[r][0], left + pad, cy));
      children.push(cell(dataRows[r][1], colX + pad, cy));
    }

    children.push({
      type: 'label', contentId: metrics[12].contentId,
      anchor: { x: W / 2, y: H * 0.955 },
      hAlign: 'center', vAlign: 'middle', color: '#5A6B7D'
    });

    return {
      schemaVersion: 1,
      sceneId: 'unit-conversion-table',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
